#!/usr/bin/env python3
# =====================================================================
#  apply_wing_fast_fill.py  —  fence WING_FAST_FILL_20261111
#  REQUIRES, in order: apply_tsg_wing_guard.py → apply_wing_reach.py →
#  apply_order_latency.py
#
#  ⚠ LIVE ORDER PATH — hedge wings of TSG_V1, IC_V1/IC_V2, TMA_V2, VET_V1.
#  Wings were bid at LTP + 1% (₹5 → 5.05, ONE tick) off a last trade that
#  can be seconds old — often at or below the ask — and IC/TMA2 then waited
#  up to 45 s with no re-price while the short waited behind the wing.
#
#   zerodha_executor.py  place_wing_buy / fresh_wing_buy_limit:
#                        best ASK + max(₹1, 20%), capped ₹3, ceil to tick
#                        (₹5.10 ask → 6.15). A limit above the ask fills at
#                        the resting offer; the extra is only a ceiling.
#                        NSE LPP for index options <= ₹50 is ±₹20 → safe.
#   execution_router.py  forwards both; executors without them (Angel,
#                        fakes) degrade to place_buy / fresh_buy_entry_limit
#   exit_order_driver.py optional fresh_fn + start_px (a re-price never
#                        LOWERS the bid); defaults unchanged for exits
#   wing_entry.py (new)  place_wing() + confirm_wing(): re-price off a fresh
#                        ask every 2 s, same caps as before (IC/TMA2 45 s,
#                        VET 15 s), then cancel + confirm as before
#   tsg / ic / tma2 / vet managers: wings use it; TSG wings re-peg every
#                        2 s × 10 (cfg wing_fill_timeout_s / wing_repeg_max)
#   UNCHANGED: every SHORT leg, every exit, and the option-BUYING
#   strategies (ORB, BRK, EMC, LVB, HA) — they keep place_buy pricing.
#   tests  test_wing_fast_fill.py (20 checks, spread-book market model:
#          old bid unfilled after 45 s, new fills at the ask at once) and
#          ic/test_ic_wing_fast_fill.py (+ the IC suites it touches)
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_wing_fast_fill.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "WING_FAST_FILL_20261111"
ITEMS = json.loads(r'''[{"path": "backend/app/execution/zerodha_executor.py", "orig": "d029aa947eaeb7cea88f7f7538a7db0d97aa6b78993c4c2600edbaf6f34e5387", "new": "43cd4932151742bd652ea8f4910caba653cfada53d10b4d4e35d3bf3dd4f58ef", "blob": ""}, {"path": "backend/app/execution/execution_router.py", "orig": "4b2af070deca80cabdb41d86d426ebdfaee8f46a95f887a8d99356012e45923c", "new": "1fd1e8dd2986e1cd6c8d46c8e357fa6d5968c2a989aa55e08cf99563999e9834", "blob": ""}, {"path": "backend/app/execution/exit_order_driver.py", "orig": "67039deb6cf0496832b747a4919d0ca13fa9e7a0da8605884e6b97aec8a6b803", "new": "776bdba6eb30e321832fc5b3dbdb33600184d4ec0408392f3e3bb60755eafec4", "blob": ""}, {"path": "backend/app/execution/wing_entry.py", "orig": null, "new": "9903827c30399b2ab6a7c82dc1489dc57395db0a350b069bc9e59dd1af699964", "blob": ""}, {"path": "backend/app/engine/tsg/tsg_manager.py", "orig": "b8e1fdb9d84e82e9f431fea002c8b8e52e42c24b57fa4b5b702f81bb6770f957", "new": "82dcead0b4497423608a8a5fd00b336f74e931a6fe465e9107c984f4e2fd5b05", "blob": ""}, {"path": "backend/app/engine/ic/ic_group_manager.py", "orig": "95e83dbda4dd4b8ee9cf505e662b525d75cb6ab2fbbb51dec91b037712bb3a6b", "new": "f8fea7b17625949d8446023b58831c6d5ff6b8c7cb05f459fcb0c016a2324c3f", "blob": ""}, {"path": "backend/app/engine/tma2/tma2_trade_manager.py", "orig": "b0df002a50d736f2ed7a98611ca7231cae4150e28d493f0c4ae2dbe09530f5db", "new": "7f25b31df8b99546369c20fd14d3bbbc1e099f26ff6cc3920b42a86b090cd696", "blob": ""}, {"path": "backend/app/engine/vet/vet_manager.py", "orig": "2bf09d89bf61c91b7b2f18316fb0d61e1ae01a7508e857aea377785535e57d71", "new": "b8041215aeb158427ca5db12115b54c21cf6611910f18523555fb1e46fc12137", "blob": ""}, {"path": "backend/app/execution/test_wing_fast_fill.py", "orig": null, "new": "15a8bd5a3415abae095e83af01add57e31ba75af36d2e2e813e495e322bff03f", "blob": ""}, {"path": "backend/app/engine/ic/test_ic_wing_fast_fill.py", "orig": null, "new": "a743efcfa8852330bc6676b095de831877eee2674a75f87923fb5177be69fae1", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/execution/test_wing_fast_fill.py", "app/engine/ic/test_ic_wing_fast_fill.py",
         "app/engine/tsg/test_tsg_e2e.py", "app/engine/tsg/test_tsg_exit_confirm.py",
         "app/engine/tsg/test_tsg_wing_guard.py",
         "app/engine/tma2/test_tma2_e2e.py", "app/engine/tma2/test_tma2_entry_paths.py",
         "app/engine/tma2/test_tma2_exit_paths.py", "app/engine/tma2/test_tma_paper_fallback.py",
         "app/engine/vet/test_vet_e2e.py", "app/engine/vet/test_vet_manager.py",
         "app/engine/vet/test_vet_wing_far.py", "app/engine/vet/test_vet_live_confirm.py",
         "app/engine/vet/test_vet_near_obs.py", "app/engine/vet/test_vet_gap_close.py",
         "app/engine/ic/test_ic2_shadow_carry.py", "app/engine/test_entry_fast_confirm.py",
         "app/engine/test_wing_reach.py", "app/execution/test_order_latency.py",
         "app/execution/test_execution_router_contract.py", "app/slippage/test_slip.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisites: the three scripts from earlier today, in order
if "--rollback" not in args:
    _need = [("TSG_WING_GUARD_20261111", "backend/app/engine/tsg/tsg_manager.py", "apply_tsg_wing_guard.py"),
             ("WING_REACH_20261111", "backend/app/engine/ic/ic_group_manager.py", "apply_wing_reach.py"),
             ("ORDER_LATENCY_20261111", "backend/app/execution/zerodha_executor.py", "apply_order_latency.py")]
    for _f, _p, _s in _need:
        try:
            _ok = _f in open(os.path.join(repo, _p), encoding="utf-8").read()
        except OSError:
            _ok = False
        if not _ok:
            die(f"run {_s} first — this script builds on {_f}")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="wing_fast_fill_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend)
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=600)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_wing_fast_fill.py --rollback")
